        {
          "step": 2,
          "action": "linkedin_input_collection",
          "output": "name, title, about, profile_url validated and stored",
          "blocking": true
        },
        {
          "step": 3,
          "action": "job_application_context",
          "output": "is_job_application=Y/N, job_req_number, job_title if applicable",
