    "linkedin_input_collection": {
      "execution_gate": "BLOCKING",
      "prompt_template": "Please provide the following LinkedIn profile details:\n\n1. **Name:** [Full name]\n2. **Title:** [Current title]\n3. **About:** [Paste About section]\n4. **Profile URL:** [LinkedIn URL]\n\nAll fields required. Type 'SKIP' only if unavailable.",
