  "reasoning_configuration_validation": {
    "purpose": "v17 NEW - Catch reasoning configuration errors before K-node execution to prevent invalid parameter combinations",
    "execution_point": "After Section 3 completion, before first K-node (K.1) execution",
    "blocking_severity": ["CRITICAL"],
    "warning_severity": ["WARNING"],
    "info_severity": ["INFO"],

    "validation_rules": [
      {
        "rule_id": "LIC-QA-001",
        "name": "Hybrid_COT_TOT requires ToT enabled",
        "check": "IF Hybrid_COT_TOT='ON' THEN ToT='ON'",
        "severity": "CRITICAL",
        "rationale": "Cannot have hybrid reasoning without ToT component",
        "fix": "Set ToT='ON' OR set Hybrid_COT_TOT='OFF'"
      },
      {
        "rule_id": "LIC-QA-002",
        "name": "ToT enabled requires branch parameters",
        "check": "IF ToT='ON' THEN TOT_MIN_BRANCHES >= 2 AND TOT_MAX_BRANCHES >= TOT_MIN_BRANCHES AND TOT_MIN_DEPTH >= 1",
        "severity": "CRITICAL",
        "rationale": "ToT needs branch count and depth configuration",
        "fix": "Set TOT_MIN_BRANCHES >= 2, TOT_MAX_BRANCHES >= TOT_MIN_BRANCHES, TOT_MIN_DEPTH >= 1"
      },
      {
        "rule_id": "LIC-QA-003",
        "name": "CoT enabled requires beam_width >= 1",
        "check": "IF CoT='ON' THEN beam_width >= 1",
        "severity": "CRITICAL",
        "rationale": "CoT beam search needs at least 1 parallel reasoning chain",
        "fix": "Set beam_width >= 1 (recommended: 2-5 for self-consistency)"
      },
      {
        "rule_id": "LIC-QA-004",
        "name": "Self-consistency requires multiple runs",
        "check": "IF SelfConsistencyRuns exists THEN SelfConsistencyRuns >= 2",
        "severity": "CRITICAL",
        "rationale": "Cannot perform majority vote with only 1 run",
        "fix": "Set SelfConsistencyRuns >= 2"
      },
      {
        "rule_id": "LIC-QA-005",
        "name": "RAG_Mode requires minimum retrievers",
        "check": "IF RAG_Mode='ON' THEN RAG_Min_Retrievers >= 1",
        "severity": "CRITICAL",
        "rationale": "Cannot perform retrieval without at least 1 retriever",
        "fix": "Set RAG_Min_Retrievers >= 1"
      },
      {
        "rule_id": "LIC-QA-006",
        "name": "AGENTIC_MODE requires hops configuration",
        "check": "IF AGENTIC_MODE='ON' THEN AGENTIC_MAX_HOPS >= 1",
        "severity": "CRITICAL",
        "rationale": "Agentic RAG needs at least 1 hop",
        "fix": "Set AGENTIC_MAX_HOPS >= 1"
      },
      {
        "rule_id": "LIC-QA-007",
        "name": "Agentic RAG requires RAG enabled",
        "check": "IF AGENTIC_MODE='ON' THEN RAG_Mode='ON'",
        "severity": "CRITICAL",
        "rationale": "Cannot have agentic multi-hop without base RAG enabled",
        "fix": "Set RAG_Mode='ON' OR set AGENTIC_MODE='OFF'"
      },
      {
        "rule_id": "LIC-QA-008",
        "name": "Conditional RAG requires trigger specification",
        "check": "IF RAG_Mode='CONDITIONAL' THEN RAG_Trigger must be defined",
        "severity": "CRITICAL",
        "rationale": "Conditional RAG needs explicit trigger condition",
        "fix": "Define RAG_Trigger condition (e.g., 'message_type IN [C_LEVEL, EXECUTIVE]')"
      },
      {
        "rule_id": "LIC-QA-009",
        "name": "ToT disabled should not have branch parameters",
        "check": "IF ToT='OFF' THEN TOT_MIN_BRANCHES=0 AND TOT_MAX_BRANCHES=0 AND TOT_MIN_DEPTH=0",
        "severity": "WARNING",
        "rationale": "ToT parameters have no effect when ToT disabled",
        "fix": "Set all ToT parameters to 0 OR enable ToT='ON'"
      },
      {
        "rule_id": "LIC-QA-010",
        "name": "RAG disabled should not have retriever parameters",
        "check": "IF RAG_Mode='OFF' THEN RAG_Min_Retrievers=0 AND AGENTIC_MODE='OFF'",
        "severity": "WARNING",
        "rationale": "RAG parameters have no effect when RAG disabled",
        "fix": "Set RAG_Min_Retrievers=0, AGENTIC_MODE='OFF' OR enable RAG_Mode='ON'"
      },
      {
        "rule_id": "LIC-QA-011",
        "name": "CONNECTION_REQ route forbids RAG",
        "check": "IF route='CONNECTION_REQ' THEN all K-nodes must have RAG_Mode='OFF'",
        "severity": "CRITICAL",
        "rationale": "330 char limit precludes RAG research depth (documented anti-pattern)",
        "fix": "Set RAG_Mode='OFF' for all K-nodes when route='CONNECTION_REQ'"
      },
      {
        "rule_id": "LIC-QA-012",
        "name": "K.4, K.5, K.6 should not use RAG",
        "check": "IF K in [K.4, K.5, K.6] THEN RAG_Mode='OFF'",
        "severity": "WARNING",
        "rationale": "Documented anti-patterns: no ROI from RAG for attachments, CTA, or signatures",
        "fix": "Set RAG_Mode='OFF' for K.4, K.5, K.6"
      },
      {
        "rule_id": "LIC-QA-013",
        "name": "Temperature range validation",
        "check": "IF temperature exists THEN 0.0 <= temperature <= 2.0",
        "severity": "CRITICAL",
        "rationale": "Temperature outside valid range will cause API errors",
        "fix": "Set temperature between 0.0 and 2.0"
      },
      {
        "rule_id": "LIC-QA-014",
        "name": "Top_p range validation",
        "check": "IF top_p exists THEN 0.0 < top_p <= 1.0",
        "severity": "CRITICAL",
        "rationale": "Top_p outside valid range will cause API errors",
        "fix": "Set top_p between 0.0 (exclusive) and 1.0 (inclusive)"
      },
      {
        "rule_id": "LIC-QA-015",
        "name": "Repetition_penalty range validation",
        "check": "IF repetition_penalty exists THEN repetition_penalty >= 1.0",
        "severity": "CRITICAL",
        "rationale": "Repetition penalty < 1.0 encourages repetition (likely unintended)",
        "fix": "Set repetition_penalty >= 1.0"
      },
      {
        "rule_id": "LIC-QA-016",
        "name": "K.3 requires high RAG investment for executives",
        "check": "IF K='K.3' AND message_type IN ['C_LEVEL', 'EXECUTIVE'] THEN RAG_Min_Retrievers >= 5 AND AGENTIC_MAX_HOPS >= 3",
        "severity": "WARNING",
        "rationale": "v16 documented: K.3 executive deep research is HIGHEST ROI use case",
        "fix": "Set RAG_Min_Retrievers=5, AGENTIC_MAX_HOPS=3 for K.3 executives"
      },
      {
        "rule_id": "LIC-QA-017",
        "name": "Reflexion requires both reviewers",
        "check": "IF Reflexion='ON' THEN specialist_reviewer AND ga_reviewer must be configured in persona_mapping",
        "severity": "WARNING",
        "rationale": "Reflexion needs both specialist and GA reviewers for two-round review",
        "fix": "Configure specialist_reviewer and ga_reviewer personas OR set Reflexion='OFF'"
      },
      {
        "rule_id": "LIC-QA-018",
        "name": "SHOW_DETAILED_REASONING toggle compatibility",
        "check": "SHOW_DETAILED_REASONING applies only to Section 4 output format, does not disable reasoning execution",
        "severity": "INFO",
        "rationale": "Reminder: reasoning always executes internally, toggle only controls display verbosity"
      },
      {
        "rule_id": "LIC-QA-019",
        "name": "Job application enrichment requires K.3",
        "check": "IF is_job_application='Y' THEN K.3 must execute (not skipped by route)",
        "severity": "CRITICAL",
        "rationale": "Cannot apply job application framing without message body (K.3)",
        "fix": "Route must include K.3 execution OR set is_job_application='N'"
      },
      {
        "rule_id": "LIC-QA-020",
        "name": "Route-message_type compatibility",
        "check": "IF route='CONNECTION_REQ' THEN message_type must be 'SHORT_NEW'",
        "severity": "CRITICAL",
        "rationale": "CONNECTION_REQ route forces SHORT_NEW due to 330 char limit",
        "fix": "Use different route OR accept message_type='SHORT_NEW'"
      },
      {
        "rule_id": "LIC-QA-021",
        "name": "Message type transition requires K.3 regeneration",
        "check": "IF transition_detected THEN K.3 regeneration_capable='true'",
        "severity": "CRITICAL",
        "rationale": "v20: Cannot transition message types without K.3 regeneration",
        "fix": "Enable K.3 regeneration capability"
      },
      {
        "rule_id": "LIC-QA-022",
        "name": "K.3 expanded format validation",
        "check": "IF K.3 transitioning from SHORT_NEW THEN word_count >= 40",
        "severity": "CRITICAL",
        "rationale": "v20: Expanded format must meet minimum word count",
        "fix": "Ensure K.3 expansion meets word requirements"
      },
      {
        "rule_id": "LIC-QA-023",
        "name": "K.4 attachment requirement after transition",
        "check": "IF transition from SHORT_NEW to SENIOR_TA THEN K.4 must add attachment",
        "severity": "WARNING",
        "rationale": "v20: SENIOR_TA messages typically include resume",
        "fix": "Enable K.4 attachment addition on transition"
      }
    ],

