  "rag_source_prioritization": {
    "purpose": "Configure source-type weighting and query strategies to prioritize high-signal content like podcasts and video interviews",
    "execution_point": "Applied during K.1, K.2 (conditional), and K.3 RAG retrieval",
    "version": "v2_podcast_priority",

    "global_source_weighting": {
      "purpose": "Apply consistent source-type multipliers across all RAG-enabled K-nodes",

      "tier_1_premium_sources": {
        "source_types": ["podcast_appearance", "video_interview", "conference_talk", "webinar_guest"],
        "weight_multiplier": 1.5,
        "rationale": "Rich conversational content reveals thinking patterns, unscripted insights, and authentic voice",
        "recency_boost": {
          "last_3_months": 1.8,
          "last_6_months": 1.5,
          "last_12_months": 1.2,
          "older_than_12_months": 1.0
        }
      },

      "tier_2_primary_sources": {
        "source_types": ["earnings_call", "investor_presentation", "authored_blog_post", "linkedin_article", "company_announcement"],
        "weight_multiplier": 1.2,
        "rationale": "Direct from source, but more scripted/polished than conversational media"
      },

      "tier_3_secondary_sources": {
        "source_types": ["news_article", "press_release", "trade_publication"],
        "weight_multiplier": 1.0,
        "rationale": "Filtered through media; useful but less direct"
      },

      "tier_4_low_signal_sources": {
        "source_types": ["aggregated_content", "syndicated_news", "generic_bio"],
        "weight_multiplier": 0.5,
        "rationale": "Low signal quality; use only if higher tiers unavailable"
      }
    },

    "podcast_specific_retrieval": {
      "purpose": "Specialized strategies for discovering and prioritizing podcast content",

      "search_query_templates": {
        "primary_patterns": [
          "{recipient_name} podcast guest",
          "{recipient_name} podcast interview",
          "{recipient_name} appeared on podcast",
          "podcast {recipient_name} {company_name}",
          "{recipient_name} {domain_keyword} podcast"
        ],
        "platform_specific": {
          "apple_podcasts": "{recipient_name} site:podcasts.apple.com",
          "spotify": "{recipient_name} podcast site:open.spotify.com",
          "youtube_audio": "{recipient_name} interview OR podcast site:youtube.com",
          "listen_notes": "{recipient_name} (via Listen Notes API if available)"
        }
      },

      "detection_keywords": {
        "strong_signals": ["podcast", "episode", "guest on", "interview with", "hosted by", "appeared on"],
        "weak_signals": ["discussion", "talk", "conversation", "chat with"],
        "platforms": ["Apple Podcasts", "Spotify", "YouTube", "Stitcher", "Google Podcasts", "Listen Notes"]
      },

      "scoring_algorithm": {
        "base_score_formula": "relevance_score * 0.5",
        "source_type_boost": "1.5 if podcast, 1.3 if video_interview, 1.0 default",
        "recency_boost": "1.8 if <3mo, 1.5 if <6mo, 1.2 if <12mo, 1.0 if older",
        "final_score_formula": "base_score * source_type_boost * recency_boost",
        "minimum_podcast_inclusion": "If podcast found with score >=0.6, include even if other sources score higher (up to 1 podcast per hop)"
      }
    },

    "k_node_specific_strategies": {
      "K.1_routing_rag": {
        "podcast_priority": "MEDIUM",
        "retrieval_focus": "Recent LinkedIn activity patterns, company org signals",
        "podcast_use_case": "If recipient has podcast appearances discussing role/industry, use as behavioral signal",
        "query_template": "{recipient_name} podcast {industry} OR {recipient_name} LinkedIn activity"
      },

      "K.2_subject_rag": {
        "podcast_priority": "HIGH",
        "retrieval_focus": "Most recent recipient content (last 30 days)",
        "podcast_use_case": "Reference recent podcast appearance in subject line for attention-grabbing hook",
        "query_template": "{recipient_name} podcast recent OR {recipient_name} latest interview",
        "conditional": "Only for C_LEVEL/EXECUTIVE message types"
      },

      "K.3_body_rag": {
        "podcast_priority": "CRITICAL",
        "retrieval_focus": "Deep research into recipient's thinking, priorities, and domain expertise",
        "podcast_use_case": "Extract unscripted insights, authentic voice, strategic priorities from conversational media",
        "multi_hop_strategy": {
          "hop_1": {
            "query": "{recipient_name} podcast guest OR {recipient_name} video interview (prioritize last 12 months)",
            "target_sources": 3,
            "minimum_podcast_sources": 1,
            "fallback": "If no podcast: search earnings calls, blog posts, LinkedIn articles"
          },
          "hop_2": {
            "query": "IF hop_1 found podcast: Extract 2-3 key topics discussed → search '{recipient_name} {topic}' across all source types. IF no podcast: Extract strategic priorities from fallback sources",
            "target_sources": 4,
            "cross_reference": "Compare podcast insights with written content for consistency"
          },
          "hop_3": {
            "query": "Search recipient LinkedIn activity (last 180 days) for posts/comments related to hop_1/hop_2 topics",
            "target_sources": 3,
            "synthesis": "Connect podcast insights → company strategy → recipient's own LinkedIn voice"
          }
        },
        "message_type_variations": {
          "C_LEVEL": {
            "retrievers": 20,
            "hops": 6,
            "podcast_minimum": "Aim for 2+ podcast sources across all hops",
            "rationale": "C-suite messaging requires deepest research; podcasts reveal board-level thinking"
          },
          "EXECUTIVE": {
            "retrievers": 12,
            "hops": 4,
            "podcast_minimum": "Aim for 1-2 podcast sources",
            "rationale": "Executive messaging benefits from conversational insights"
          },
          "SENIOR_TA": {
            "retrievers": 12,
            "hops": 4,
            "podcast_minimum": "Aim for 1 podcast source if available",
            "rationale": "TA leaders often discuss team-building on podcasts"
          },
          "RECRUITER": {
            "retrievers": 9,
            "hops": 4,
            "podcast_minimum": "0-1 podcast sources (nice-to-have)",
            "rationale": "Recruiters less likely to have podcast presence; prioritize job postings/LinkedIn"
          }
        }
      }
    },

    "retrieval_execution_flow": {
      "step_1_query_formulation": {
        "action": "Generate search query using podcast_specific_retrieval.search_query_templates",
        "apply_filters": ["recency (prefer <12mo)", "platform hints", "detection keywords"]
      },
      "step_2_source_retrieval": {
        "action": "Execute search across available retrieval systems",
        "return": "Top N sources with metadata (source_type, date, platform, url)"
      },
      "step_3_source_classification": {
        "action": "Classify each source into tier (premium/primary/secondary/low_signal)",
        "detect_podcasts": "Scan for detection_keywords in title, description, url"
      },
      "step_4_scoring": {
        "action": "Apply scoring_algorithm to each source",
        "rank": "Sort by final_score DESC"
      },
      "step_5_selection": {
        "action": "Select top K sources for synthesis",
        "enforce_minimum_podcast_inclusion": "If podcast source exists with score >=0.6, include at least 1 podcast even if lower-ranked"
      },
      "step_6_synthesis": {
        "action": "Extract insights from selected sources",
        "podcast_extraction": "For podcast sources, focus on: unscripted moments, strategic priorities mentioned, domain expertise demonstrated, thinking patterns",
        "merge_strategy": "Combine podcast insights (tier 1) with written content (tier 2) for comprehensive view"
      }
    },

    "quality_gates": {
      "minimum_signal_quality": 0.65,
      "podcast_bonus": "If >=1 podcast source with quality >=0.7, add +0.05 to aggregate signal quality",
      "fallback_behavior": "If no podcast sources found after hop 1, proceed with tier 2/3 sources without blocking",
      "audit_logging": "Log podcast retrieval attempts, success rate, and impact on message quality"
    },

    "anti_patterns": {
      "do_not_force_podcast_references": "If no podcast found, do NOT fabricate podcast mentions or use phrases like 'I heard you on...' without evidence",
      "do_not_over_weight_old_podcasts": "Podcasts >24 months old receive recency_boost=0.8 (penalty) unless highly relevant",
      "do_not_ignore_other_sources": "Podcasts are premium but not exclusive; still retrieve and consider tier 2/3 sources"
    }
  },

